from itertools import product

# Define elements and multiplication table
elements = ['e', 'a', 'h', 'b', 'g', 'z', 'ep', 'd']
# a=alpha, h=eta, b=beta, g=gamma, z=zeta, ep=epsilon, d=delta

# Table rows (row * col)
table = {
    'e':  ['e', 'a', 'h', 'b', 'g', 'z', 'ep', 'd'],
    'a':  ['a', 'h', 'b', 'e', 'z', 'ep', 'd', 'g'],
    'h':  ['h', 'b', 'e', 'a', 'ep', 'd', 'g', 'z'],
    'b':  ['b', 'e', 'a', 'h', 'd', 'g', 'z', 'ep'],
    'g':  ['g', 'z', 'ep', 'd', 'e', 'a', 'h', 'b'],
    'z':  ['z', 'ep', 'd', 'g', 'a', 'h', 'b', 'e'],
    'ep': ['ep', 'd', 'g', 'z', 'h', 'b', 'e', 'a'],
    'd':  ['d', 'g', 'z', 'ep', 'b', 'e', 'a', 'h'],
}

def mul(x, y):
    return table[x][elements.index(y)]

# Check identity
for x in elements:
    assert mul(x, 'e') == x, f"{x}*e != {x}"
    assert mul('e', x) == x, f"e*{x} != {x}"
print("Identity OK")

# Check orders
for x in elements:
    power = x
    for n in range(1, 9):
        if power == 'e':
            print(f"order({x}) = {n}")
            break
        power = mul(power, x)
    else:
        print(f"order({x}) = >8 ??")

# Check commutativity
non_commuting = []
for x in elements:
    for y in elements:
        if mul(x, y) != mul(y, x):
            non_commuting.append((x, y))
print(f"\nNon-commuting pairs: {len(non_commuting)}")
if non_commuting:
    for p in non_commuting[:5]:
        print(f"  {p[0]}*{p[1]} = {mul(*p)}, {p[1]}*{p[0]} = {mul(p[1],p[0])}")

# Check associativity
assoc_fail = 0
for x in elements:
    for y in elements:
        for z in elements:
            if mul(mul(x, y), z) != mul(x, mul(y, z)):
                assoc_fail += 1
                if assoc_fail <= 3:
                    print(f"Assoc fail: ({x}*{y})*{z} = {mul(mul(x,y),z)}, {x}*({y}*{z}) = {mul(x,mul(y,z))}")
print(f"\nAssociativity failures: {assoc_fail}")

# Check inverses
print("\nInverses:")
for x in elements:
    for y in elements:
        if mul(x, y) == 'e':
            print(f"  {x}^-1 = {y}")
            break
