            non_abelian.append((x, y, mul(x, y), mul(y, x)))
if non_abelian:
    print(f"非交换! 共 {len(non_abelian)} 对不交换")
    for x, y, xy, yx in non_abelian[:5]:
        print(f"  {x}*{y} = {xy}, {y}*{x} = {yx}")
else:
    print("群是交换的 (abelian)")

# 3. 计算每个元素的阶
