    for a, b, c, lhs, rhs in assoc_errors[:5]:
        print(f"  ({a}*{b})*{c} = {lhs}, {a}*({b}*{c}) = {rhs}")
else:
    print("结合律成立")

# 5. 验证逆元存在
print("\n=== 逆元 ===")
for x in elem_list:
    for y in elem_list:
        if mul(x, y) == 'e':
            print(f"  {x}⁻¹ = {y}")
            break

# 6. 计算共轭类
print("\n=== 共轭类 ===")
conjugates = {x: set() for x in elem_list}
for a in elem_list:
    for g in elem_list:
        # g⁻¹
        g_inv = None
        for y in elem_list:
            if mul(g, y) == 'e':
                g_inv = y
                break
        # gag⁻¹
        result = mul(mul(g, a), g_inv)
        conjugates[a].add(result)

# 去重共轭类
seen = set()
classes = []
for x in elem_list:
    cls = frozenset(conjugates[x])
    if cls not in seen:
        seen.add(cls)
        classes.append(cls)
        print(f"  {x} 的共轭类: {sorted(cls)}")

print(f"\n共轭类个数: {len(classes)}")
for i, cls in enumerate(classes):
    print(f"  C{i+1} = {sorted(cls)}")
